def build_contexts(traces, K):
    contexts = []
    for tr in traces:
        rows = tr["rows"]
        n = len(rows)
        if n < K:
            continue
        vals = [r[1] for r in rows]
        times = [r[0] for r in rows]
        tid = tr["id"]
        src = tr["source"]
        for i in range(n - K + 1):
            contexts.append((tuple(vals[i:i + K]), tid, src, times[i + K - 1]))
    return contexts


