def has_dollar(node):
    keys = set(node.keys())
    if keys == {"field", "at"}:
        return node["at"] == "$"
    if keys == {"scale", "term"}:
        return has_dollar(node["term"])
    if keys == {"add"}:
        return has_dollar(node["add"][0]) or has_dollar(node["add"][1])
    return False


